import os, json, subprocess, socket
root = "E:\\0zhongqi"
out = {}
for name in sorted(os.listdir(root)):
    p = os.path.join(root, name)
    if os.path.isdir(p):
        kids = []
        for k in sorted(os.listdir(p))[:40]:
            kp = os.path.join(p, k)
            try: sz = os.path.getsize(kp) if os.path.isfile(kp) else -1
            except Exception: sz = -2
            kids.append([k, sz])
        hist = {}; n = 0
        for dp, dn, fn in os.walk(p):
            for f in fn:
                e = os.path.splitext(f)[1].lower() or "<noext>"
                hist[e] = hist.get(e, 0) + 1
                n += 1
                if n > 30000: break
            if n > 30000: break
        out[name] = {"dir": True, "kids": kids, "hist": hist}
    else:
        out[name] = {"dir": False, "size": os.path.getsize(p)}
print(json.dumps(out, ensure_ascii=True))
